import{_ as e,o as l,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Code Walkthroughs: OSD Read Lease","description":"","frontmatter":{"title":"Ceph Code Walkthroughs: OSD Read Lease","date":"2021-12-02T00:00:00.000Z","updated":"2021-12-03T00:00:00.000Z","tags":["Ceph","分布式存储","读写一致性","租约机制","OSD"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Code_Walkthroughs_-_OSD_Read_Lease.md","filePath":"posts/2021/Ceph_Code_Walkthroughs_-_OSD_Read_Lease.md","lastUpdated":1780459816000}'),i={name:"posts/2021/Ceph_Code_Walkthroughs_-_OSD_Read_Lease.md"};function r(s,a,n,h,d,p){return l(),t("div",null,[...a[0]||(a[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph分布式存储系统中的读写一致性问题及解决方案" tabindex="-1">会议主题：Ceph分布式存储系统中的读写一致性问题及解决方案 <a class="header-anchor" href="#会议主题-ceph分布式存储系统中的读写一致性问题及解决方案" aria-label="Permalink to &quot;会议主题：Ceph分布式存储系统中的读写一致性问题及解决方案&quot;">​</a></h4><h4 id="会议时间-具体时间" tabindex="-1">会议时间：[具体时间] <a class="header-anchor" href="#会议时间-具体时间" aria-label="Permalink to &quot;会议时间：[具体时间]&quot;">​</a></h4><h4 id="参会人员-参会人员名单" tabindex="-1">参会人员：[参会人员名单] <a class="header-anchor" href="#参会人员-参会人员名单" aria-label="Permalink to &quot;参会人员：[参会人员名单]&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>问题背景</strong>：</p><ul><li>在Ceph中，写操作需触及所有副本以确保一致性，而读操作通常只从主副本读取。</li><li>网络分区可能导致主副本未意识到集群状态变化，继续服务旧数据读取请求，造成数据不一致。</li></ul></li><li><p><strong>历史问题</strong>：</p><ul><li>该问题在Ceph早期版本中存在，最终在Octopus版本中得到修复。</li></ul></li><li><p><strong>解决方案详述</strong>：</p><ul><li><strong>租约机制</strong>：通过租约消息在主副本和副本之间同步状态，确保读操作的一致性。</li><li><strong>时间戳处理</strong>：使用单调时钟处理时间戳，避免时钟偏差问题。</li><li><strong>租约间隔设置</strong>：通过全局配置选项设置租约间隔。</li></ul></li><li><p><strong>新引入的PG状态</strong>：</p><ul><li><strong>Laggy状态</strong>：当PG活跃但租约未及时更新时，PG进入Laggy状态，暂停读取请求。</li><li><strong>Wait状态</strong>：当PG正在进行peering且前一个间隔的上限仍在未来时，PG进入Wait状态，暂停写操作。</li></ul></li><li><p><strong>优化措施</strong>：</p><ul><li><strong>快速关闭通知</strong>：OSD可以通过发送“标记我为死亡”消息快速标记OSD为死亡。</li><li><strong>历史记录处理</strong>：在peering过程中，通过历史记录处理前一个间隔的租约状态。</li></ul></li><li><p><strong>测试与验证</strong>：</p><ul><li>通过单元测试和功能测试验证了修复方案的有效性。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>确认Octopus版本中引入的租约机制和相关优化措施有效解决了读写一致性问题。</li><li>需要进一步完善快速关闭通知机制。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续监控集群状态，确保租约机制稳定运行。</li><li>完善文档，详细记录租约机制的配置和使用方法。</li><li>定期进行性能测试，确保引入的机制不会对系统性能产生负面影响。</li></ul><h4 id="会议结束语" tabindex="-1">会议结束语： <a class="header-anchor" href="#会议结束语" aria-label="Permalink to &quot;会议结束语：&quot;">​</a></h4><p>感谢所有参会人员的积极参与和讨论，本次会议对于理解Ceph中的读写一致性问题及其解决方案具有重要意义。期待后续的实施和验证工作能够顺利进行。</p>',12)])])}const g=e(i,[["render",r]]);export{_ as __pageData,g as default};
